'use strict';

// Self-contained, invented UI scenario. Never imports repository fixtures or private answers.
const STORE_KEY = 'doezip-design-learning-v1';
const initialState = () => ({ started:false, report:'', initialReport:'', initialSubmitted:false, messages:[], activeSource:'M01', activeStatement:'S01', reviews:{}, challengeSubmitted:false, defenseEntered:false, answers:['',''], answersSubmitted:false, finalReport:'', reviseReason:'', completed:false, mobilePanel:'source', filter:'all' });
let state = initialState();
let storageAvailable = true;
try { const saved=JSON.parse(localStorage.getItem(STORE_KEY)||'null'); if(saved&&typeof saved==='object') state={...state,...saved}; } catch { storageAvailable=false; }
const $ = (s,root=document)=>root.querySelector(s);
const $$ = (s,root=document)=>[...root.querySelectorAll(s)];
const esc = value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));storageAvailable=true;}catch{storageAvailable=false;}}
const paths={arrow:'M4 12h15m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',file:'M14 3H6a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V9zm0 0v6h6M8 13h8m-8 4h6',book:'M12 5c-3-2-7-2-10-1v15c4-1 7-1 10 1m0-15c3-2 7-2 10-1v15c-4-1-7-1-10 1V5',chat:'M21 11a9 9 0 0 1-9 9H3l2-4a9 9 0 1 1 16-5ZM8 10h8m-8 4h5',clock:'M12 8v5l3 2M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',spark:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4ZM20 2v4m-2-2h4',link:'m10 13 4-4m-7 6-1 1a3.5 3.5 0 0 0 5 5l4-4a3.5 3.5 0 0 0 0-5m2-3 1-1a3.5 3.5 0 0 0-5-5L9 7a3.5 3.5 0 0 0 0 5',x:'m6 6 12 12M6 18 18 6',shield:'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7Zm-5 9 3 3 6-6',target:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0m-4 0a5 5 0 1 1-10 0 5 5 0 0 1 10 0m-5 0h.01',sprout:'M12 21V11m0 4C4 15 2 10 3 5c7-1 10 3 9 10Zm0-4c-1-6 3-9 9-8 1 6-3 9-9 8Z',refresh:'M20 7A9 9 0 1 0 21 15M20 2v6h-6',send:'m21 3-7 18-4-7-7-4Zm0 0L10 14',info:'M12 11v6m0-10h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',lock:'M7 11V7a5 5 0 0 1 10 0v4M5 11h14v10H5zm7 4v2',quote:'M4 5h6v6H5c0 3 1 4 4 5M14 5h6v6h-5c0 3 1 4 4 5',layers:'m12 3 10 5-10 5L2 8Zm-10 9 10 5 10-5M2 16l10 5 10-5'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`;
const arrow=()=>icon('arrow');
const materials=[
 {id:'M01',title:'상황 브리핑',type:'운영 메모',lines:['오후 12:04부터 일부 사용자가 결제 완료까지 오래 기다린다는 문의를 남겼습니다.','이번 과제의 목표는 제공된 자료로 확인 가능한 사실과 가설을 구분하는 것입니다.','결제 요청은 애플리케이션 서버, 데이터베이스, 외부 결제 서비스를 거칩니다.','원인 가설, 그 근거, 추가로 확인할 내용을 담은 짧은 보고서를 작성해 주세요.']},
 {id:'M02',title:'결제 API 요청 로그',type:'요청 기록',lines:['관찰 구간은 12:00부터 12:10까지입니다.','12:00~12:03의 평균 응답 시간은 약 300ms였습니다.','12:04 이후 평균 응답 시간은 약 2,400ms로 증가했습니다.','같은 구간에서 외부 결제 요청의 시간초과 기록이 증가했습니다.']},
 {id:'M03',title:'서버·DB 지표',type:'모니터링 요약',lines:['관찰 구간의 애플리케이션 서버 CPU는 약 31%였습니다.','데이터베이스 CPU 사용률은 약 24%로 유지됐습니다.','데이터베이스 연결 풀의 대기 시간과 사용량은 수집되지 않았습니다.','CPU 지표 하나만으로 모든 종류의 자원 병목을 배제할 수는 없습니다.']},
 {id:'M04',title:'외부 결제 서비스 기록',type:'연동 로그',lines:['12:04 이후 외부 결제 호출의 응답 지연이 관찰됐습니다.','일부 요청은 제한 시간을 넘겨 실패했습니다.','이 기록만으로 외부 서비스 자체의 장애인지, 호출 방식의 문제인지는 확정할 수 없습니다.']},
 {id:'M05',title:'조사 시점의 확인 사항',type:'조사 메모',lines:['운영팀은 요청 경로별 응답 시간과 설정 변경 이력을 추가 확인 중입니다.','현재 자료에는 연결 풀 고갈을 직접 확인할 수 있는 지표가 없습니다.','확인하지 못한 내용은 미확인으로 남기고, 다음 조사에 필요한 자료를 적어 주세요.']}
];
const statements=[
 {id:'S01',text:'12:04 이후 결제 API의 평균 응답 시간이 증가했습니다.'},
 {id:'S02',text:'같은 시간대 데이터베이스 CPU 사용률은 85%까지 상승했습니다.'},
 {id:'S03',text:'따라서 결제 지연의 원인은 데이터베이스 연결 풀 고갈로 확정할 수 있습니다.'},
 {id:'S04',text:'판단을 보완하기 위해 요청 경로별 지표와 설정 변경 이력을 추가 확인해야 합니다.'}
];
const judgments={keep:'그대로 유지',correct:'내용 수정',insufficient:'근거 부족'};
const sampleReport='확인한 사실\n12:04 이후 결제 API의 평균 응답 시간이 약 300ms에서 2,400ms로 증가했다. 같은 구간에 외부 결제 요청의 시간초과 기록이 있다.\n\n현재 판단\n외부 결제 호출 구간의 지연이 관련됐을 가능성이 있다. 다만 외부 서비스 자체의 장애인지는 확정하기 어렵다.\n\n추가로 확인할 것\n요청 경로별 소요 시간과 최근 설정 변경 이력을 확인하고 싶다.';
function review(id=state.activeStatement){return state.reviews[id]||(state.reviews[id]={judgment:'',reason:'',revision:'',evidence:[],saved:false});}
const savedReviews=()=>statements.filter(s=>state.reviews[s.id]?.saved);
const evidenceCount=()=>savedReviews().reduce((n,s)=>n+review(s.id).evidence.length,0);
function continuation(){return state.completed?'final':state.answersSubmitted?'revise':state.defenseEntered?'defense':state.challengeSubmitted?'feedback':state.initialSubmitted?'challenge':'workspace';}
function progressLabel(){return state.completed?'학습 완료':state.answersSubmitted?'보고서 다시 쓰기':state.defenseEntered?'되묻기':state.challengeSubmitted?'1차 피드백':state.initialSubmitted?'검산 챌린지':'분석·보고서 작성';}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 430 300" fill="none" role="img" aria-label="자료를 읽고 근거를 연결해 판단을 완성하는 노트 일러스트"><circle cx="244" cy="152" r="112" fill="#DBE7C8"/><path d="M64 233c53 23 112 14 153-9m128-155c33 39 33 75 12 96" stroke="#9BAD88" stroke-width="1.5" stroke-dasharray="4 6"/><g transform="rotate(-12 150 146)"><rect x="64" y="56" width="160" height="200" rx="10" fill="#DEE4D5"/><rect x="60" y="50" width="160" height="200" rx="10" fill="#FCFDF8" stroke="#BCCBAC"/><rect x="77" y="71" width="32" height="20" rx="4" fill="#EAF0E1"/><text x="83" y="85" font-family="Arial,sans-serif" font-size="9" fill="#56704C">M02</text><path d="M78 110h119M78 125h100M78 141h119M78 157h85M78 202h93M78 218h114" stroke="#D0D9C5" stroke-width="4" stroke-linecap="round"/><path d="M76 172h122v14H76z" fill="#D5E9A7"/><path d="M81 179h108" stroke="#92AC6F" stroke-width="3" stroke-linecap="round"/></g><g transform="rotate(7 272 159)"><rect x="188" y="79" width="163" height="193" rx="11" fill="#CAD7BC"/><rect x="183" y="72" width="163" height="193" rx="11" fill="white" stroke="#B6C7A4"/><text x="204" y="101" font-family="-apple-system,sans-serif" font-size="11" font-weight="600" fill="#375D42">나의 판단</text><path d="M205 116h114M205 131h92" stroke="#DBE2D5" stroke-width="4" stroke-linecap="round"/><rect x="201" y="150" width="126" height="67" rx="6" fill="#F0F5E9"/><path d="m213 168 4 4 7-9" stroke="#436A43" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><text x="233" y="172" font-family="-apple-system,sans-serif" font-size="10" fill="#436A43">근거를 확인했어요</text><path d="M215 187h96M215 200h73" stroke="#C5D4B4" stroke-width="3" stroke-linecap="round"/><text x="204" y="243" font-family="Arial,sans-serif" font-size="9" letter-spacing="1" fill="#8C9E7C">THINK. VERIFY. GROW.</text></g><path d="M150 181c30 31 39 15 56 4" stroke="#577F4E" stroke-width="2" stroke-linecap="round"/><path d="m199 182 10 1-4 9" stroke="#577F4E" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><g transform="rotate(12 336 64)"><rect x="299" y="37" width="85" height="35" rx="17.5" fill="#255846"/><path d="m313 54 4 4 7-8" stroke="#D5E9A7" stroke-width="1.7" stroke-linecap="round"/><text x="331" y="58" font-family="-apple-system,sans-serif" font-size="10" fill="#fff">한 번 더</text></g><path d="m83 37 2-9m8 15 8-5m-32 6-7-5" stroke="#8EA472" stroke-width="2" stroke-linecap="round"/></svg>`;}
function problemArt(){return `<div class="problem-art"><svg viewBox="0 0 240 230" fill="none" role="img" aria-label="결제 요청 경로와 응답 시간 기록"><circle cx="122" cy="120" r="84" stroke="#D3DEC6"/><circle cx="122" cy="120" r="63" stroke="#DEE6D4"/><path d="M58 79h72v57h54" stroke="#A2B78C" stroke-width="1.5" stroke-dasharray="4 4"/><rect x="23" y="53" width="87" height="61" rx="8" fill="#fff" stroke="#B9CAA9"/><rect x="33" y="65" width="16" height="16" rx="4" fill="#EAF0E1"/><path d="m39 70-3 3 3 3m4-6 3 3-3 3" stroke="#6C8757" stroke-width="1.3"/><text x="55" y="76" font-family="Arial,sans-serif" font-size="8" fill="#52674A">PAYMENT API</text><path d="M35 96h12l5-5 7 10 6-19 8 19 5-5h20" stroke="#749558" stroke-width="1.5" stroke-linecap="round"/><rect x="108" y="125" width="108" height="71" rx="8" fill="#255846"/><text x="121" y="144" font-family="Arial,sans-serif" font-size="8" fill="#B3C8AD">RESPONSE TIME</text><text x="121" y="168" font-family="Arial,sans-serif" font-size="21" font-weight="600" fill="#EBF6DF">2,400<tspan font-size="9" font-weight="400"> ms</tspan></text><path d="M122 182h15l7-4 9 1 7-9 8 7 9-8 13 2 13-9" stroke="#BDD691" stroke-width="1.4"/><circle cx="174" cy="61" r="20" fill="#D5E9A7"/><path d="M174 52v12m0 5h.01" stroke="#43673D" stroke-width="2" stroke-linecap="round"/><circle cx="62" cy="163" r="5" fill="#A9C187"/></svg></div>`;}
const breadcrumb=(label)=>`<div class="breadcrumb"><a href="#explore">문제 탐색</a>${icon('chevron')}<span>${label}</span></div>`;
function stages(current){const rows=[['workspace','분석·작성',state.started],['challenge','검산',state.initialSubmitted],['feedback','피드백',state.challengeSubmitted],[state.answersSubmitted?'revise':'defense','되묻기·수정',state.challengeSubmitted],['final','최종 리포트',state.completed]];return `<ol class="stage-bar" aria-label="학습 단계">${rows.map(([r,label,allowed],i)=>`<li class="${i===current?'current':i<current?'done':''}"><button data-route="${r}" ${allowed?'':'disabled'} ${i===current?'aria-current="step"':''}><span>${i<current?icon('check'):String(i+1).padStart(2,'0')}</span>${label}</button></li>`).join('')}</ol>`;}
function problemCard(){return `<article class="problem-card">${problemArt()}<div class="problem-card-body"><div class="pill-row"><span class="pill">개발 · 장애 분석</span>${state.started?`<span class="pill ${state.completed?'':'amber'}">${state.completed?'학습 완료':'진행 중'}</span>`:''}</div><h3><a href="#detail">결제는 왜 갑자기<br>느려졌을까?</a></h3><p class="description">흩어진 운영 자료를 읽고,<br>장애 원인을 근거로 설명해 보세요.</p><div class="problem-meta"><span>${icon('target')}입문</span><span>${icon('clock')}약 30분 · 예상</span><span>${icon('file')}자료 5개</span></div><div class="card-bottom"><span class="small muted">근거 검증 · 문서화</span><a class="text-link" href="#${state.started?continuation():'detail'}">${state.started?(state.completed?'리포트 보기':'이어서 풀기'):'문제 살펴보기'}${arrow()}</a></div></div></article>`;}
function emptyFiltered(){return `<div class="empty-state">${icon('book')}<h2>${state.filter==='completed'?'완료한 문제가 아직 없어요':'아직 풀고 있는 문제가 없어요'}</h2><p>첫 문제를 선택하고, 나만의 근거를 쌓아보세요.</p><button class="btn secondary" data-action="filter" data-filter="all">모든 문제 보기 ${arrow()}</button></div>`;}
function explore(){const show=state.filter==='all'||(state.filter==='progress'&&state.started&&!state.completed)||(state.filter==='completed'&&state.completed);return `<div class="container fade-in"><section class="hero"><div class="hero-copy"><div class="eyebrow">배운 것을, 나의 판단으로</div><h1>AI와 함께 풀고,<br><em>내 근거로 완성하세요.</em></h1><p class="description">실무의 문제를 고르고, AI의 답을 확인하며<br>스스로 설명할 수 있는 결과를 만들어보세요.</p><div class="hero-bottom"><a href="#detail" class="btn primary">첫 문제 만나보기 ${arrow()}</a><span class="small">한 문제에서 시작하는 생각의 변화</span></div></div>${heroArt()}</section>${state.started&&!state.completed?`<div class="resume-strip"><div><strong>풀던 문제, 이어서 해볼까요?</strong><p>결제는 왜 갑자기 느려졌을까? · ${progressLabel()}</p></div><a href="#${continuation()}" class="btn soft small-btn">이어서 풀기 ${arrow()}</a></div>`:''}<section aria-labelledby="problem-heading"><div class="section-heading"><h2 id="problem-heading">지금 풀 수 있는 문제 <span>1</span></h2><div class="filters" aria-label="문제 상태 필터">${[['all','모든 문제'],['progress','진행 중'],['completed','완료']].map(([key,label])=>`<button class="filter ${state.filter===key?'active':''}" aria-pressed="${state.filter===key}" data-action="filter" data-filter="${key}">${label}</button>`).join('')}</div></div><div class="explore-grid"><div>${show?problemCard():emptyFiltered()}</div><aside class="learning-note"><h3>한 문제를, 세 번 깊게.</h3><div class="mini-step"><span>01</span><div><strong>함께 분석하고</strong><p>원본 자료를 읽고<br>AI와 생각을 넓혀보세요.</p></div></div><div class="mini-step"><span>02</span><div><strong>근거로 확인하고</strong><p>답변 속 판단을 살펴보고<br>내 말로 이유를 남겨보세요.</p></div></div><div class="mini-step"><span>03</span><div><strong>다시 생각해요</strong><p>새로운 정보와 피드백으로<br>처음의 판단을 발전시켜요.</p></div></div><p class="note-foot">현재는 첫 번째 과제로 학습 흐름을 경험할 수 있어요.</p></aside></div></section></div>`;}
function detail(){return `<div class="container fade-in">${breadcrumb('문제 소개')}<section class="detail-head"><div><div class="pill-row"><span class="pill">개발 · 장애 분석</span><span class="pill neutral">입문</span></div><h1>결제는 왜 갑자기<br>느려졌을까?</h1><p class="description">자료 속 사실을 연결하고, 확인되지 않은 것은 구분해 보세요.<br>문제를 풀며 근거 있는 원인 분석 보고서를 완성합니다.</p><div class="problem-meta"><span>${icon('clock')}예상 30분</span><span>${icon('file')}원본 자료 5개</span><span>${icon('sprout')}근거 검증 · 문서화</span></div></div>${problemArt()}</section><div class="detail-grid"><div><section class="content-section"><h2>오늘의 상황</h2><div class="brief-box"><div class="quote-mark">“</div><p>점심 무렵, 결제가 평소보다 오래 걸린다는 문의가 들어왔어요. 운영팀은 여러 기록을 모았지만 아직 원인을 확정하지 못했습니다.<br><br>당신은 제공된 자료와 AI를 활용해 상황을 분석하고, 팀에 공유할 짧은 보고서를 작성하게 됩니다.</p></div></section><section class="content-section"><h2>어떤 자료가 있나요?</h2><div class="source-list">${materials.map(m=>`<div class="source-row">${icon('file')}<span>${m.title}</span><span class="source-id">${m.id}</span></div>`).join('')}</div></section><section class="content-section"><h2>이 연습을 마치면</h2><p>확인된 사실과 가설을 구분하고, 판단에 자료의 근거를 연결할 수 있어요. 피드백과 새로운 정보를 받은 뒤에는 처음의 보고서를 다시 살펴보게 됩니다.</p></section></div><aside class="detail-aside"><h3>이렇게 진행해요</h3><div class="learning-path"><div class="path-item"><span>1</span><div>자료 분석·보고서 작성<small>AI와 생각을 정리해요</small></div></div><div class="path-item"><span>2</span><div>검산 챌린지<small>별도의 초안을 근거로 검토해요</small></div></div><div class="path-item"><span>3</span><div>피드백·되묻기<small>내 판단을 설명해요</small></div></div><div class="path-item"><span>4</span><div>보고서 수정·전후 비교<small>새 정보로 한 번 더 생각해요</small></div></div></div><button class="btn primary block" data-action="start">${state.started?'이어서 학습하기':'이 문제 시작하기'} ${arrow()}</button><p class="tiny-note">시안의 작성 내용은 이 브라우저에 저장돼요.</p></aside></div></div>`;}
function sourcePanel(challenge=false){const m=materials.find(m=>m.id===state.activeSource)||materials[0], r=review();return `<section class="panel ${state.mobilePanel==='source'?'mobile-active':''}" data-panel="source"><header class="panel-header"><h2>${icon('book')}원본 자료</h2><span class="pill neutral">5개</span></header><div class="panel-body"><label class="sr-only" for="source-select">열람할 원본 자료</label><select id="source-select" class="source-picker">${materials.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${x.id} · ${x.title}</option>`).join('')}</select><h3 class="document-title">${m.title}</h3><p class="document-meta">${m.id} · ${m.type} · UI 검토용 가상 자료</p><div class="source-lines">${m.lines.map((line,i)=>{const eid=`${m.id}-L${i+1}`,selected=challenge&&r.evidence.includes(eid);return challenge&&!state.challengeSubmitted?`<button class="source-line interactive ${selected?'selected':''}" aria-pressed="${selected}" data-action="evidence" data-evidence="${eid}"><span class="ln">L${i+1}</span><span>${line}</span></button>`:`<div class="source-line readonly ${selected?'selected':''}"><span class="ln">L${i+1}</span><span>${line}</span></div>`;}).join('')}</div><p class="source-foot">${icon(challenge?'link':'info')} ${challenge?'근거로 삼을 줄을 선택하면 검토에 연결돼요.':'각 자료의 시간과 관찰 범위를 함께 확인해 보세요.'}</p></div></section>`;}
function mobileTabs(kind){const options=kind==='challenge'?[['source','자료'],['statements','검산 초안'],['review','내 검토']]:[['source','자료'],['chat','AI와 분석'],['editor','내 보고서']];return `<div class="mobile-tabs" role="group" aria-label="작업 영역 선택">${options.map(([p,label])=>`<button aria-pressed="${state.mobilePanel===p}" class="${state.mobilePanel===p?'active':''}" data-action="panel" data-panel="${p}">${label}${kind==='challenge'&&p==='review'&&review().evidence.length?` · 근거 ${review().evidence.length}`:''}</button>`).join('')}</div>`;}
function chatPanel(){return `<section class="panel ${state.mobilePanel==='chat'?'mobile-active':''}" data-panel="chat"><header class="panel-header"><h2>${icon('chat')}AI와 분석</h2><span class="pill neutral">예시 대화</span></header><div class="panel-body"><div class="chat-messages" id="chat-messages"><div class="chat-message"><span class="chat-avatar">↶</span><div class="message-content"><div class="message-label">되짚 학습 도우미 · 예시</div><p>함께 자료를 살펴볼까요?\n\n먼저 확인된 사실과 아직 모르는 것을 나눠보면 좋아요. 어떤 자료부터 보고 싶나요?</p></div></div>${state.messages.map(m=>`<div class="chat-message ${m.role==='user'?'user':''}"><span class="chat-avatar">${m.role==='user'?'나':'↶'}</span><div class="message-content"><div class="message-label">${m.role==='user'?'나':'미리 작성된 예시 응답'}</div><p>${esc(m.text)}</p>${m.role==='assistant'?`<button class="evidence-link" data-action="open-material" data-source="M02">${icon('file')}M02 요청 로그 보기 ${icon('arrow')}</button>`:''}</div></div>`).join('')}</div><div class="chat-hints"><button data-action="chat-example" data-prompt="어떤 자료부터 확인하면 좋을까?">어떤 자료부터 볼까요?</button><button data-action="chat-example" data-prompt="사실과 가설을 어떻게 나눌까?">사실과 가설 구분하기</button></div><form id="chat-form"><div class="chat-composer"><label class="sr-only" for="chat-input">AI에게 질문하기</label><textarea id="chat-input" placeholder="궁금한 점을 질문해 보세요" rows="2" maxlength="2000"></textarea><button class="icon-btn" aria-label="질문 보내기" type="submit">${icon('send')}</button></div></form><p class="composer-note">화면 체험용 대화예요. 실제 AI를 호출하지 않아요.</p></div></section>`;}
function workspace(){return `<div class="container wide fade-in">${breadcrumb('결제는 왜 갑자기 느려졌을까?')}${stages(0)}<div class="workspace-top"><div><h1>자료를 읽고, 나만의 가설을 세워보세요.</h1><p class="description">AI와 함께 분석하되, 보고서에는 직접 확인한 근거를 담아주세요.</p></div><span class="pill outline">01 · 분석과 작성</span></div>${state.initialSubmitted?`<div class="review-readonly">${icon('lock')} 최초 제출한 보고서입니다. 피드백과 되묻기를 마치면 새 버전으로 수정할 수 있어요.</div>`:''}${mobileTabs('workspace')}<div class="work-grid">${sourcePanel()}${chatPanel()}<section class="panel ${state.mobilePanel==='editor'?'mobile-active':''}" data-panel="editor"><header class="panel-header"><h2>${icon('file')}내 보고서</h2>${!state.initialSubmitted?'<button class="quiet" data-action="sample-report">작성 예시 넣기</button>':'<span class="pill neutral">제출됨</span>'}</header><div class="panel-body"><p class="editor-help">확인한 사실, 현재 판단, 추가로 확인할 것을 적어보세요.</p><label class="sr-only" for="report-editor">나의 원인 분석 보고서</label><textarea id="report-editor" class="editor" placeholder="확인한 사실\n자료에서 직접 확인한 내용은 무엇인가요?\n\n현재 판단\n어떤 원인을 생각하고 있나요?\n\n추가로 확인할 것\n무엇을 더 알아야 확신할 수 있나요?" maxlength="15000" ${state.initialSubmitted?'readonly':''}>${esc(state.initialSubmitted?state.initialReport:state.report)}</textarea><div class="editor-footer"><span id="report-length">${(state.initialSubmitted?state.initialReport:state.report).length}자</span><span class="save-state" id="report-save">${icon('check')}${storageAvailable?(state.report?'저장됨':'작성 전'):'브라우저 저장 불가 · 현재 화면에서만 유지'}</span></div><p id="report-error" class="form-error" role="alert"></p></div><div class="panel-action"><button class="btn primary block" data-action="begin-challenge">${state.initialSubmitted?'검산으로 돌아가기':'보고서 저장하고 검산하기'} ${arrow()}</button></div></section></div><p class="flow-note">${icon('shield')}작성한 보고서와 다음 단계의 검산용 AI 초안은 별도로 보관돼요.</p></div>`;}
